-- 읽기 전용 검증 (적용 후) — 모두 true 여야 한다.
select
  (select d like '%-- pg_unknown_origin_guard begin%' and d like '%-- pg_unknown_origin_guard end%' from (select pg_get_functiondef('public._refund_membership_core(uuid,uuid,boolean,boolean)'::regprocedure) d) x)              as unknown_origin_guard_present_must_be_true,
  (select d like '%o.payment_provider is not null and o.payment_provider <> ''mock''%' from (select pg_get_functiondef('public._refund_membership_core(uuid,uuid,boolean,boolean)'::regprocedure) d) x)                          as allowlist_present_must_be_true,
  (select d !~ 'o\.payment_provider\s+in\s*\(\s*''toss''\s*,\s*''portone''\s*\)' from (select pg_get_functiondef('public._refund_membership_core(uuid,uuid,boolean,boolean)'::regprocedure) d) x)                              as old_denylist_active_must_be_false_inverted_true,
  (select prosecdef from pg_proc where oid = 'public._refund_membership_core(uuid,uuid,boolean,boolean)'::regprocedure)                                                                                                         as security_definer_must_be_true,
  (select 'search_path=public' = any (proconfig) from pg_proc where oid = 'public._refund_membership_core(uuid,uuid,boolean,boolean)'::regprocedure)                                                                            as search_path_pinned_must_be_true,
  not has_function_privilege('authenticated', 'public._refund_membership_core(uuid,uuid,boolean,boolean)', 'execute')                                                                                                            as helper_not_callable_by_authenticated_must_be_true,
  not has_function_privilege('service_role',  'public._refund_membership_core(uuid,uuid,boolean,boolean)', 'execute')                                                                                                            as helper_not_callable_by_service_role_must_be_true;
